def actions(l):return '<div class="actions">'+download(l)+'<a class="button secondary" href="'+path('guide',l)+'">'+e(D[l]['install'])+'</a></div>'
def badges(l):return '<div class="compat"><span>'+icon('windows')+'Windows 7</span><span>'+icon('pc')+e(D[l]['weak'])+'</span><span>'+icon('globe')+'RU / DE / EN</span></div>'
def plaque(l):return '<a class="downloader-plaque" href="'+path('downloader',l)+'"><img src="extension/icons/icon128.png" width="43" height="43" alt=""><span class="plaque-copy"><strong>YouTube Downloader</strong><small>'+e(D[l]['extension'])+'</small></span><span class="plaque-more">'+e(D[l]['more'])+icon('arrow')+'</span></a>'
def shot(l):return '<figure class="product-shot"><img src="assets/site/peakmp3-'+l+'.webp" width="973" height="1616" alt="PeakMP3 — '+e(D[l]['density'])+'" fetchpriority="high"></figure>'
def footer(l):
 d=D[l];steps=[]
 for n,(label,i) in enumerate(zip(d['flow'],['play','file','wave','note'])):
  picture='<svg class="flow-wave" viewBox="0 0 32 32" aria-hidden="true"><path d="M5 12v8M10.5 7v18M16 3v26M21.5 7v18M27 12v8" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round"/></svg>' if i=='wave' else icon(i)
  steps.append('<li class="flow-step"><span class="flow-icon'+(' orange' if n in [0,2] else '')+'">'+picture+'</span><span class="flow-label">'+e(label)+'</span></li>')
  if n<3: steps.append('<li class="flow-connector" aria-hidden="true"><svg viewBox="0 0 64 24"><path d="M3 12h55M49 4l9 8-9 8"/></svg></li>')
 return '<footer class="workflow-wrap"><div class="workflow"><ol class="workflow-list" aria-label="YouTube → AAC → PeakMP3 → MP3">'+''.join(steps)+'</ol><div class="footer-links"><a href="https://github.com/popovantondev/YouTubeDownloader" target="_blank" rel="noreferrer">GitHub</a><a href="'+path('guide',l)+'">'+e(d['nav'][2])+'</a><a href="https://github.com/popovantondev/YouTubeDownloader/issues/new/choose" target="_blank" rel="noreferrer">'+e(d['support'])+'</a><a href="'+path('guide',l)+'#rights">'+e(d['rights'])+'</a></div></div></footer>'
def feature_row(items):return '<div class="features">'+''.join('<article><span class="feature-number">0'+str(i+1)+'</span><h3>'+e(title)+'</h3><p>'+e(text)+'</p></article>' for i,(title,text) in enumerate(items))+'</div>'
def home(l):
 d=D[l];return '<main id="content"><section class="hero"><div class="hero-copy reveal"><h1 class="hero-title">'+''.join('<span>'+e(x)+'</span>' for x in d['headline'])+'</h1><p class="suite-title">YouTube Downloader + PeakMP3</p><p class="lead">'+e(d['lead'])+'</p>'+plaque(l)+actions(l)+badges(l)+'</div>'+shot(l)+'</section></main><div class="wood-divider"></div>'+footer(l)
